function validate(input) {
  const [{ patients = [], covid_tests = [] }] = input;
  const known = new Set(), names = new Set(), tests = new Set();
  for (const [id, name, age] of patients) {
    if (id === null || name === null) return 'patient_id and patient_name cannot be null.';
    if (known.has(id)) return `patient_id ${id} appears twice in patients.`;
    known.add(id);
    const key = String(name).toLowerCase();
    if (names.has(key)) return `The name ${name} appears twice in patients.`;
    names.add(key);
    if (age !== null && age < 0) return 'age cannot be negative.';
  }
  for (const [id, patient, day, result] of covid_tests) {
    if ([id, patient, day, result].includes(null)) return 'No value in covid_tests may be null.';
    if (tests.has(id)) return `test_id ${id} appears twice in covid_tests.`;
    tests.add(id);
    if (!known.has(patient)) return `patient_id ${patient} is not in patients.`;
    if (!['Positive', 'Negative', 'Inconclusive'].includes(result)) return `Unknown result ${result}.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) return `test_date ${day} must look like 2023-01-31.`;
  }
  return null;
}

