function generate(rand, size) {
  const small = size === 'small';
  const int = n => Math.floor(rand() * n);
  const first = ['Alice', 'Bob', 'Carol', 'David', 'Emma', 'Frank', 'Grace', 'Henry', 'Ivy', 'Jack', 'Kara', 'Liam', 'Mia', 'Noah', 'Olga', 'Paul', 'Quinn', 'Rosa', 'Sam', 'Tara'];
  const last = ['Smith', 'Johnson', 'Davis', 'Wilson', 'Brown', 'Lee', 'Kim', 'Patel', 'Garcia', 'Chen', 'Novak', 'Silva', 'Moreau', 'Rossi', 'Haas', 'Berg', 'Ito', 'Okafor', 'Diaz', 'Young'];
  const day = offset => new Date(Date.UTC(2022, 11, 20) + offset * 86400000).toISOString().slice(0, 10);
  const results = ['Positive', 'Positive', 'Negative', 'Negative', 'Inconclusive'];
  const shift = int(400), count = small ? int(6) : 400, cap = small ? 8 : 2000;
  const patients = [], tests = [];
  for (let id = 1; id <= count; id++) {
    const k = (shift + id) % 400;
    patients.push([id, `${first[k % 20]} ${last[Math.floor(k / 20)]}`, 18 + int(60)]);
    // Tests come in date order with gaps of 0 to 9 days, so same-day tests and ties in recovery time happen.
    let offset = int(30);
    for (let n = int(small ? 5 : 7); n > 0; n--) {
      tests.push([id, day(offset), results[int(results.length)]]);
      offset += int(10);
    }
  }
  for (let i = tests.length - 1; i > 0; i--) { const j = int(i + 1); [tests[i], tests[j]] = [tests[j], tests[i]]; }
  const covid_tests = tests.slice(0, cap).map((test, i) => [i + 1, ...test]);
  return [{ patients, covid_tests }];
}
